// this screen's KPI cards, gallery, progress panel, and trend
// chart depend on. Order matters — collections that reference
// colReportsInScope must be built AFTER it.
// ============================================================

// ------------------------------------------------------------
// 1. FILTER STATE — screen-local UI variables, reset every visit
// ------------------------------------------------------------
Set(varHomeFilter, "All");           // KPI card selection (All/PendingApprovals/Overdue/Approved)
Set(varHomeSearchTerm, "");          // Search box text
Set(varFilterFY, "All");             // Financial Year dropdown
Set(varFilterProgramme, "All");      // Programme dropdown
Set(varFilterDirectorate, "All");    // Directorate dropdown (cascades off Programme)
Set(varFilterQuarter, "All");        // Quarter dropdown
Set(varFilterDirectorateID, "All");  // filter Monthlyreports or colReportsInScope


// Set once, outside the gallery — controls overall chart scale
// (a fixed max height in pixels that represents 100% of TotalActivities)
// Suggested: create this as a single variable in OnVisible for easy tuning

// ------------------------------------------------------------
// 2. BASE SCOPE — every report this user is allowed to see
//    Contributors/Supervisors/ProgrammeManagers: own Directorate/Programme only
//    DeputyDirectorME/Administrator: everything (varCanViewAllReports = true)
// ------------------------------------------------------------
ClearCollect(
    colReportsInScope,
    Filter(
        MonthlyReports,
        varCanViewAllReports
            || DirectorateLabel = varUserDirectorateID
            || DirectorateLabel = varUserDirectorate
            || ProgrammeLabel = varUserProgramme
    )
);

// ------------------------------------------------------------
// 3. NOTIFICATIONS — always personal, never scoped by directorate
// ------------------------------------------------------------
ClearCollect(
    colMyNotifications,
    Filter(Notifications, RecipientUser.Email = varUserEmail, IsRead = false)
);
Set(varUnreadCount, CountRows(colMyNotifications));

// ------------------------------------------------------------
// 4. MY ACTIVITIES — always personal (this user's own assigned activities)
// ------------------------------------------------------------
ClearCollect(
    colMyActivities,
    Filter(Activities, ActivityOwner.Email = varUserEmail, 'Active ' = true)
);

// ------------------------------------------------------------
// 5. PENDING APPROVALS — only meaningful for reviewer roles
// ------------------------------------------------------------
ClearCollect(
    colPendingApprovals,
    If(
        varUserRole in ["Supervisor", "ProgrammeManager", "DeputyDirectorME", "Administrator"],
        Filter(colReportsInScope, Status.Value = "Submitted", 'FinancialYear '.Value = varCurrentFY),
        Table()
    )
);

