With(
    {
        overdueScoped: Filter(
            colReportsInScope,
            IsOverdue = true,
            (varFilterFY = "All" || 'FinancialYear '.Value = varFilterFY),
            (varFilterProgramme = "All" || ProgrammeLabel = varFilterProgramme),
            (varFilterDirectorateID = "All" || DirectorateLabel = varFilterDirectorateID),
            (varFilterQuarter = "All" || Quarter.Value = varFilterQuarter)
        ),
        lastMonthName: Text(DateAdd(Date(Year(Today()), Month(Today()), 1), -1, TimeUnit.Months), "mmmm")
    },
    With(
        {
            overdueLastMonth: CountRows(Filter(overdueScoped, ReportingMonth.Value = lastMonthName)),
            overdueThisMonth: CountRows(Filter(overdueScoped, ReportingMonth.Value = varCurrentMonth))
