// Get last month's name, handling the April year-wrap correctly
// (if current month is January, "last month" is December of the previous calendar year — but
// since your FY starts in April, wrapping from April back to March is the only edge case that matters here)
With(
    {
        lastMonthName: Text(DateAdd(Date(Year(Today()), Month(Today()), 1), -1, TimeUnit.Months), "mmmm")
    },
    With(
